// generated by build — admin dashboard (only served to a logged-in admin) and login page
export const APP_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>FIT FUEL — Admin</title>\n<style>\n:root{--bg:#07231a;--bg2:#0a2d21;--card:#0e3828;--line:#1d5240;--text:#eef6f1;--muted:#9db3a6;--acc:#f29a1f;--ok:#3ddc97;--bad:#ff6b6b}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\nh1,h2,h3{margin:0}button,input,select{font:inherit}\n.wrap{max-width:1100px;margin:0 auto;padding:20px}\nheader{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px}\nheader b{font-size:20px}header b span{color:var(--acc)}\n.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:20px}\n.btn,.pill{border:1.5px solid var(--line);background:var(--bg2);color:var(--text);border-radius:999px;padding:9px 18px;cursor:pointer}\n.pill.on,.btn.pri{background:var(--acc);border-color:var(--acc);color:#0b1410;font-weight:700}\n.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:18px}\n.in{width:100%;background:var(--bg);border:1.5px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px}\n.in:focus{outline:2px solid var(--acc);border-color:var(--acc)}\nlabel{display:block;font-weight:600;margin:0 0 6px}\n.f{margin-bottom:16px}.row{display:flex;gap:10px;flex-wrap:wrap}.g2{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.muted{color:var(--muted);font-size:14px}.err{color:var(--bad);min-height:20px;margin-top:8px}\n.msg{padding:10px 14px;border-radius:10px;background:rgba(61,220,151,.12);border:1px solid rgba(61,220,151,.4)}.msg.bad{background:rgba(255,107,107,.12);border-color:rgba(255,107,107,.4)}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}@media(max-width:720px){.kpis{grid-template-columns:1fr 1fr}.g2{grid-template-columns:1fr}}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px}.kpi b{display:block;font-size:26px;color:var(--acc)}.kpi.warn b{color:var(--bad)}\n.tw{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:560px}\nth{text-align:left;color:var(--muted);font-size:12.5px;text-transform:uppercase;letter-spacing:.05em;padding:8px 10px;border-bottom:1px solid var(--line)}\ntd{padding:10px;border-bottom:1px solid var(--line);vertical-align:top}\n.bar{height:8px;border-radius:99px;background:var(--acc);min-width:6px}\n.badge{display:inline-block;font-size:12px;font-weight:700;padding:2px 9px;border-radius:99px;background:var(--line)}.badge.ok{background:rgba(61,220,151,.2);color:var(--ok)}.badge.warn{background:rgba(255,107,107,.2);color:var(--bad)}.badge.pa{background:rgba(255,200,87,.2);color:#ffc857}\n#login{max-width:400px;margin:12vh auto}\n[hidden]{display:none!important}\n@media print{body{background:#fff;color:#000}header .btn,.tabs,.noprint{display:none!important}.card,.kpi{background:#fff;border-color:#999;color:#000}.kpi b,.bar{color:#000;background:#000}th,td{color:#000;border-color:#999}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n <div id=\"app\">\n  <header><b>FIT <span>FUEL</span> · Admin</b><button class=\"btn\" id=\"out\" type=\"button\">Sign out</button></header>\n  <div class=\"tabs\" role=\"group\" aria-label=\"Admin sections\">\n   <button class=\"pill on\" data-t=\"kitchen\" type=\"button\">Kitchen sheet</button>\n   <button class=\"pill\" data-t=\"offers\" type=\"button\">Offers &amp; codes</button>\n   <button class=\"pill\" data-t=\"orders\" type=\"button\">Customers</button>\n  </div>\n  <div id=\"main\"></div>\n </div>\n</div>\n<script>\nconst RAW=`Breakfast|Shakshuka|25|250|18|15|15|267\nBreakfast|French Toast|25|250|20|70|20|540\nBreakfast|Chicken Cheese Roll|25|180|22|40|14|374\nBreakfast|Egg Sandwich|25|180|20|40|18|402\nBreakfast|Oatmeal|20|150|6|23|5|161\nBreakfast|Eggs Benedict|30|180|20|27|22|386\nBreakfast|Egg Spanish Wrap|25|175|18|35|14|338\nBreakfast|White Egg Omelette|25|170|17|5|9|169\nBreakfast|Garden Omelette|25|150|14|6|11|179\nSandwich|Chicken Quesadilla|30|250|35|50|25|565\nSandwich|Chicken Wrap|30|250|33|50|18|494\nSandwich|Burrito|30|250|33|50|18|494\nSandwich|Crispy Chicken Burger|30|250|33|55|28|604\nSandwich|Beef Steak Wrap|30|170|24|32|15|359\nSandwich|BBQ Beef Burger|38|200|30|36|24|480\nSandwich|Club Sandwich|30|200|24|40|16|400\nSandwich|BBQ Crispy Chicken Burger|30|185|24|41|20|440\nSandwich|Spicy Chicken Burger|30|200|26|44|22|478\nSandwich|Spicy Chicken Wrap|30|200|26|40|14|390\nSandwich|Low Carb Beef Burger|35|180|29|25|16|360\nSandwich|Angus Burger|30|200|30|32|24|464\nSandwich|Chicken Taco Wrap|30|185|24|37|13|361\nSandwich|Buffalo Chicken Burger|30|200|26|44|22|478\nSandwich|Beef & Cheese Quesadilla|30|200|28|40|20|452\nSandwich|Steak Sandwich|30|200|28|38|18|426\nSandwich|Chicken Slider Burger|28|180|25|34|18|398\nSandwich|Salmon Burger|35|220|31|37|22|470\nSandwich|Smash Burger|40|220|33|37|33|577\nSandwich|Beef Taco Wrap|30|185|26|35|17|397\nSandwich|Zinger Chicken Wrap|30|185|24|37|13|361\nSandwich|Beef Slider Burger|30|250|35|48|25|557\nSandwich|Low Carb Chicken Burger|30|250|40|35|23|507\nMain Dish|Creamy Meatballs|35|300|42|18|33|537\nMain Dish|Crispy Shrimp|35|300|45|42|27|591\nMain Dish|Grilled Chicken|30|300|36|39|12|408\nMain Dish|Beef Kebab|40|300|36|36|21|477\nMain Dish|Salmon Skewer|40|300|33|36|21|465\nMain Dish|Grilled Steak|40|300|36|36|21|477\nMain Dish|Chicken Burrito|30|300|33|48|15|459\nMain Dish|Chicken Snack Bowl|30|250|28|40|13|389\nMain Dish|Lemon Chicken|30|300|36|39|12|408\nMain Dish|Crispy Salmon|40|300|33|36|21|465\nMain Dish|Mattafy Salmon|40|300|33|36|21|465\nMain Dish|Chicken Masala|35|300|33|30|21|441\nMain Dish|Mattafy Chicken|30|300|36|39|12|408\nMain Dish|Chicken Biryani|30|300|24|66|15|495\nMain Dish|Grilled Salmon Avocado|45|300|33|36|21|465\nMain Dish|Creamy Zaatar Chicken|30|300|33|30|21|441\nMain Dish|Butter Chicken|30|300|33|30|21|441\nMain Dish|Chicken Garlic|30|300|36|39|12|408\nMain Dish|Creamy Dynamite Chicken|30|300|33|30|21|441\nMain Dish|BBQ Beef|40|300|36|36|21|477\nMain Dish|Sweet & Spicy Meatballs|35|300|42|18|33|537\nMain Dish|Chicken Spicy Snack Bowl|30|300|33|48|15|459\nMain Dish|Shrimp Biryani|35|300|24|66|15|495\nMain Dish|Chicken Curry|30|300|33|30|21|441\nMain Dish|Chicken Fried Rice|30|300|24|66|15|495\nMain Dish|Orange Chicken|30|300|33|48|15|459\nMain Dish|Grilled Fish|30|300|33|36|9|357\nMain Dish|Chicken Kebab|30|300|36|39|12|408\nMain Dish|BBQ Chicken|30|300|36|39|12|408\nMain Dish|Chicken Tandoori|30|300|36|39|12|408\nMain Dish|Creamy Salmon|40|150|17|18|11|239\nMain Dish|Grilled Sea Bass|40|150|17|18|5|185\nMain Dish|Shrimp Fried Rice|35|300|24|66|15|495\nHealthy Pasta|Shrimp Penne Pasta|35|300|24|57|15|459\nHealthy Pasta|Chicken Pasta|30|300|27|57|15|471\nHealthy Pasta|Shrimp Risotto|35|300|21|60|18|486\nHealthy Pasta|Spaghetti Meatballs Pasta|35|300|24|57|18|486\nHealthy Pasta|Spaghetti Bolognese Pasta|35|300|24|57|18|486\nHealthy Pasta|Salmon Risotto|35|300|21|60|18|486\nHealthy Pasta|Vegetable Pasta|25|300|12|66|12|420\nHealthy Pasta|Fettuccine Chicken Alfredo|35|300|27|54|24|540\nHealthy Pasta|Chicken Penne Arrabbiata Pasta|30|300|27|57|15|471\nHealthy Pasta|Fettuccine Shrimp|35|300|24|57|15|459\nHealthy Pasta|Chicken Risotto|30|300|21|60|18|486\nSoft Drink|Coke Zero|5|0|0|0|0|0\nSoft Drink|Sprite Zero|5|0|0|0|0|0\nSoft Drink|Pepsi Zero|5|0|0|0|0|0\nSoft Drink|7Up Zero|5|0|0|0|0|0\nFresh Juice|Orange Juice|20|175|1|18|0|76\nFresh Juice|Avocado Juice|20|175|3|16|11|175\nFresh Juice|Banana Juice|20|175|2|35|2|166\nFresh Juice|Protein Shake|25|175|25|14|4|192\nDessert|Cheesecake Peanuts|25|150|9|42|27|447\nDessert|Cheesecake Mango|25|150|9|42|27|447\nDessert|Brownies|20|130|7|59|29|525\nDessert|Pistachio Cheesecake|30|130|8|36|23|383\nDessert|Chocolate Cookies|20|120|7|66|26|526\nDessert|Greek Yogurt Bowl|25|150|12|23|5|185\nDessert|Protein Balls|20|100|15|35|15|335\nDessert|Mango Bowl|20|150|5|33|8|224\nDessert|Overnight Oats|20|150|9|27|8|216\nAcai|Acai King Peanut|30|200|8|50|12|340\nAcai|Acai Bowl|30|200|8|50|12|340\nAcai|Acai Smoothie|25|175|4|35|7|219`;\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst ITEMS=RAW.trim().split('\\n').map((l,i)=>{const[c,n,p,g]=l.split('|');return{id:'m'+i,cat:c,name:n,price:+p}});\nconst find=id=>ITEMS.find(x=>x.id===id);\nconst SLOTS=['Breakfast','Lunch','Dinner','Extra'];\nconst iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\nconst today=()=>iso(new Date());\nconst lbl=i=>new Date(i+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'});\nlet S={tab:'kitchen',date:iso(new Date(Date.now()+864e5)),subs:[],codes:[],site:{pct:0,scope:'first'},nc:{n:'',c:'',pct:10,max:'',exp:''},err:''};\n\nasync function api(path,o={}){\n  const h={};if(o.body){h['Content-Type']='application/json'}if(o.method&&o.method!=='GET')h['X-Requested-With']='ff-admin';\n  const r=await fetch(path,{method:o.method||'GET',headers:h,credentials:'same-origin',body:o.body?JSON.stringify(o.body):undefined});\n  const j=await r.json().catch(()=>({}));\n  if(r.status===401&&path!=='/api/admin/login'){showLogin();throw new Error('Please log in.')}\n  if(!r.ok)throw new Error(j.error||('Error '+r.status));return j}\nfunction showLogin(){location.reload()}\nasync function start(){try{await load();render()}catch(e){}}\nasync function load(){\n  const [o,c,s]=await Promise.all([fetch('/api/offers').then(r=>r.json()),api('/api/codes'),api('/api/subscriptions')]);\n  S.site=o;S.codes=c.codes;S.subs=s.subs}\n\n$('#out').addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST'})}catch(e){}showLogin()});\ndocument.querySelector('.tabs').addEventListener('click',e=>{const b=e.target.closest('[data-t]');if(!b)return;S.tab=b.dataset.t;document.querySelectorAll('.tabs .pill').forEach(x=>x.classList.toggle('on',x===b));render()});\n\n/* ---- kitchen ---- */\nfunction rosterFor(date){return S.subs.filter(u=>u.status!=='cancelled').map(u=>({u,day:u.days.find(d=>d.d===date)})).filter(x=>x.day)}\nfunction vKitchen(){\n  const all=rosterFor(S.date),R=all.filter(x=>!x.day.skip),agg={};let meals=0,al=0;\n  R.forEach(({u,day})=>{Object.keys(day.picks).forEach(s=>{const it=find(day.picks[s]);if(!it)return;(agg[s]=agg[s]||{})[it.name]=(agg[s][it.name]||0)+1;meals++});if((u.alg&&u.alg.length)||u.excl)al++});\n  const mx=Math.max(1,...Object.values(agg).flatMap(o=>Object.values(o)));\n  return `<div class=\"card\"><div class=\"row\" style=\"justify-content:space-between;align-items:end\"><div><h3>Kitchen prep sheet</h3><p class=\"muted\" style=\"margin:4px 0 0\">Live orders from the database.</p></div>\n  <div class=\"row noprint\" style=\"align-items:end\"><div><label for=\"kd\">Delivery date</label><input class=\"in\" type=\"date\" id=\"kd\" value=\"${S.date}\"></div><button class=\"btn pri\" id=\"pr\" type=\"button\">Print</button></div></div></div>\n  <div class=\"kpis\"><div class=\"kpi\"><b>${R.length}</b>Customers to deliver</div><div class=\"kpi\"><b>${meals}</b>Meals to prep</div><div class=\"kpi ${al?'warn':''}\"><b>${al}</b>Allergy / exclusion alerts</div><div class=\"kpi\"><b>${all.length-R.length}</b>Skipped / paused</div></div>\n  <div class=\"card\"><h3 style=\"margin-bottom:10px\">Total meals to cook (by dish)</h3><div class=\"tw\"><table><tr><th>Meal</th><th>Dish</th><th style=\"width:34%\">Qty</th></tr>\n  ${SLOTS.filter(s=>agg[s]).map(s=>Object.entries(agg[s]).sort((a,b)=>b[1]-a[1]).map(([k,v],i)=>`<tr><td>${i?'':'<b>'+s+'</b>'}</td><td>${esc(k)}</td><td><div class=\"row\" style=\"align-items:center;flex-wrap:nowrap\"><div class=\"bar\" style=\"width:${v/mx*100}%\"></div><b>${v}</b></div></td></tr>`).join('')).join('')||'<tr><td colspan=\"3\" class=\"muted\">No meals to prepare on this date.</td></tr>'}</table></div></div>\n  <div class=\"card\"><h3 style=\"margin-bottom:10px\">Pack list per customer</h3><div class=\"tw\"><table><tr><th>Customer</th><th>Zone · Address</th><th>Meals</th><th>Flags</th></tr>\n  ${R.map(({u,day})=>`<tr><td><b>${esc(u.name)}</b><br><span class=\"muted\">${esc(u.phone)}</span></td><td>${esc(u.zone)}<br><span class=\"muted\">${esc(u.slot)} · ${esc(u.address)}</span></td><td>${Object.keys(day.picks).map(s=>`<div><span class=\"muted\">${s}</span> ${esc((find(day.picks[s])||{name:'?'}).name)}</div>`).join('')}</td><td>${(u.alg||[]).concat(u.excl?[u.excl]:[]).map(a=>`<span class=\"badge warn\">No ${esc(a)}</span> `).join('')||'<span class=\"badge ok\">None</span>'}</td></tr>`).join('')||'<tr><td colspan=\"4\" class=\"muted\">No deliveries on this date.</td></tr>'}</table></div></div>`}\n\n/* ---- offers ---- */\nfunction vOffers(){const n=S.nc;return `<div class=\"card\"><h3>Subscription discount</h3><p class=\"muted\">Customers always see the original price first, then the discount at checkout.</p>\n <div class=\"f\"><label>Discount on monthly subscriptions</label><div class=\"row\">${[0,10,15,20,25].map(p=>`<button type=\"button\" class=\"pill ${S.site.pct==p?'on':''}\" data-a=\"site\" data-v=\"${p}\">${p?p+'% off':'Off'}</button>`).join('')}</div></div>\n <div class=\"f\"><label>Applies to</label><div class=\"row\">${[['first','First month only'],['all','Every monthly renewal']].map(([k,t])=>`<button type=\"button\" class=\"pill ${S.site.scope==k?'on':''}\" data-a=\"scope\" data-v=\"${k}\">${t}</button>`).join('')}</div></div>\n <div class=\"msg ${S.site.pct?'':'bad'}\">${S.site.pct?`✅ ${S.site.pct}% discount is <b>live</b> for all new subscribers.`:'No site-wide discount is running. Customers pay the original price.'}</div></div>\n <div class=\"card\"><h3>Create a promo code</h3><p class=\"muted\">For sponsors. If a customer has both an offer and a code they get the bigger one, not both.</p>\n <div class=\"g2\"><div class=\"f\"><label for=\"pn\">Sponsor name</label><input class=\"in\" id=\"pn\" value=\"${esc(n.n)}\" placeholder=\"e.g. Sara Fitness\"></div><div class=\"f\"><label for=\"pc\">Code (blank = auto)</label><input class=\"in\" id=\"pc\" value=\"${esc(n.c)}\" placeholder=\"e.g. SARA15\" style=\"text-transform:uppercase\"></div></div>\n <div class=\"f\"><label>Discount</label><div class=\"row\">${[10,15,20,25].map(p=>`<button type=\"button\" class=\"pill ${n.pct==p?'on':''}\" data-a=\"npct\" data-v=\"${p}\">${p}%</button>`).join('')}</div></div>\n <div class=\"g2\"><div class=\"f\"><label for=\"pm\">Max uses (blank = unlimited)</label><input class=\"in\" id=\"pm\" type=\"number\" min=\"0\" value=\"${esc(n.max)}\"></div><div class=\"f\"><label for=\"px\">Expires (optional)</label><input class=\"in\" id=\"px\" type=\"date\" value=\"${esc(n.exp)}\"></div></div>\n ${S.err?`<div class=\"err\">${esc(S.err)}</div>`:''}<button class=\"btn pri\" type=\"button\" data-a=\"mk\">Create code</button></div>\n <div class=\"card\"><h3 style=\"margin-bottom:10px\">Promo codes</h3>${S.codes.length?`<div class=\"tw\"><table><tr><th>Code</th><th>Sponsor</th><th>Off</th><th>Used</th><th>Expires</th><th>Status</th><th></th></tr>${S.codes.map(c=>{const ex=c.exp&&c.exp<today(),fu=c.max&&c.used>=c.max,st=!c.active?'<span class=\"badge pa\">Paused</span>':ex?'<span class=\"badge warn\">Expired</span>':fu?'<span class=\"badge warn\">Limit reached</span>':'<span class=\"badge ok\">Active</span>';return `<tr><td><b>${esc(c.code)}</b></td><td>${esc(c.sponsor||'—')}</td><td>${c.pct}%</td><td>${c.used}${c.max?' / '+c.max:''}</td><td>${c.exp?lbl(c.exp):'—'}</td><td>${st}</td><td style=\"white-space:nowrap\"><button class=\"pill\" type=\"button\" data-a=\"copy\" data-v=\"${esc(c.code)}\">Copy</button> <button class=\"pill\" type=\"button\" data-a=\"tgl\" data-v=\"${esc(c.code)}\">${c.active?'Pause':'Resume'}</button> <button class=\"pill\" type=\"button\" data-a=\"del\" data-v=\"${esc(c.code)}\">Delete</button></td></tr>`}).join('')}</table></div>`:'<p class=\"muted\" style=\"margin:0\">No codes yet.</p>'}</div>`}\n\n/* ---- customers ---- */\nfunction vOrders(){return `<div class=\"card\"><h3 style=\"margin-bottom:10px\">Customers (${S.subs.length})</h3><div class=\"tw\"><table><tr><th>ID</th><th>Customer</th><th>Plan</th><th>Zone</th><th>Discount</th><th>Status</th><th>Created</th></tr>\n ${S.subs.map(u=>`<tr><td>${esc(u.id)}</td><td><b>${esc(u.name)}</b><br><span class=\"muted\">${esc(u.phone)}</span></td><td>${u.plan} days · ${u.meals} meals · ${esc(u.diet)}</td><td>${esc(u.zone)}</td><td>${u.pct?u.pct+'%'+(u.code?' ('+esc(u.code)+')':''):'—'}</td><td>${u.status==='cancelled'?'<span class=\"badge warn\">Cancelled</span>':u.paused?'<span class=\"badge pa\">Paused</span>':'<span class=\"badge ok\">Active</span>'}</td><td>${esc((u.created||'').slice(0,10))}</td></tr>`).join('')||'<tr><td colspan=\"7\" class=\"muted\">No customers yet.</td></tr>'}</table></div></div>`}\n\nfunction render(){$('#main').innerHTML=S.tab==='kitchen'?vKitchen():S.tab==='offers'?vOffers():vOrders()}\nconst main=$('#main');\nmain.addEventListener('input',e=>{const t=e.target;if(t.id==='pn')S.nc.n=t.value;if(t.id==='pc')S.nc.c=t.value;if(t.id==='pm')S.nc.max=t.value;if(t.id==='px')S.nc.exp=t.value});\nmain.addEventListener('change',e=>{if(e.target.id==='kd'){S.date=e.target.value||S.date;render()}});\nmain.addEventListener('click',async e=>{\n  if(e.target.id==='pr'){window.print();return}\n  const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a,v=b.dataset.v;S.err='';\n  try{\n    if(a==='site'){S.site.pct=+v;await api('/api/offers',{method:'PUT',body:{pct:S.site.pct,scope:S.site.scope}})}\n    else if(a==='scope'){S.site.scope=v;await api('/api/offers',{method:'PUT',body:{pct:S.site.pct,scope:v}})}\n    else if(a==='npct'){S.nc.pct=+v}\n    else if(a==='mk'){const n=S.nc;let code=(n.c||'').toUpperCase().replace(/[^A-Z0-9]/g,'');if(!code)code=((n.n||'PROMO').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'PROMO')+n.pct;\n      await api('/api/codes',{method:'POST',body:{code,sponsor:n.n.trim(),pct:n.pct,max:+n.max||0,exp:n.exp||''}});S.nc={n:'',c:'',pct:n.pct,max:'',exp:''};await load()}\n    else if(a==='tgl'){const c=S.codes.find(x=>x.code===v);await api('/api/codes/'+encodeURIComponent(v),{method:'PATCH',body:{active:!c.active}});await load()}\n    else if(a==='del'){if(!confirm('Delete code '+v+'?'))return;await api('/api/codes/'+encodeURIComponent(v),{method:'DELETE'});await load()}\n    else if(a==='copy'){try{await navigator.clipboard.writeText(v);b.textContent='Copied ✓'}catch(_){prompt('Copy code:',v)}return}\n  }catch(er){S.err=er.message}\n  render()});\nstart();\n</script>\n</body>\n</html>\n";
export const LOGIN_HTML = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex, nofollow\"><title>FIT FUEL — Admin login</title>\n<style>:root{--bg:#07231a;--card:#0e3828;--line:#1d5240;--text:#eef6f1;--muted:#9db3a6;--acc:#f29a1f;--bad:#ff6b6b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\n.card{max-width:400px;margin:12vh auto;padding:24px;background:var(--card);border:1px solid var(--line);border-radius:18px}h2{margin:0 0 6px}.muted{color:var(--muted)}label{display:block;font-weight:600;margin:0 0 6px}\n.in{width:100%;background:var(--bg);border:1.5px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px;font:inherit}.in:focus{outline:2px solid var(--acc);border-color:var(--acc)}.f{margin-bottom:16px}\n.btn{border:0;background:var(--acc);color:#0b1410;font:inherit;font-weight:700;border-radius:999px;padding:10px 22px;cursor:pointer}.err{color:var(--bad);min-height:20px;margin-top:8px}</style></head>\n<body><div class=\"card\"><h2>FIT <span style=\"color:var(--acc)\">FUEL</span> admin</h2><p class=\"muted\">Sign in to manage orders, discounts and promo codes.</p>\n<form id=\"lf\" autocomplete=\"on\"><div class=\"f\"><label for=\"u\">Username</label><input class=\"in\" id=\"u\" name=\"username\" autocomplete=\"username\" required></div>\n<div class=\"f\"><label for=\"p\">Password</label><input class=\"in\" id=\"p\" name=\"password\" type=\"password\" autocomplete=\"current-password\" required></div>\n<button class=\"btn\" type=\"submit\">Sign in</button><div class=\"err\" id=\"lerr\" role=\"alert\"></div></form></div>\n<script>document.getElementById('lf').addEventListener('submit',async function(e){e.preventDefault();var er=document.getElementById('lerr');er.textContent='';\ntry{var r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ff-admin'},credentials:'same-origin',body:JSON.stringify({user:document.getElementById('u').value,password:document.getElementById('p').value})});\nvar j=await r.json().catch(function(){return{}});if(!r.ok)throw new Error(j.error||('Error '+r.status));location.reload()}catch(x){er.textContent=x.message}});</script></body></html>";
